inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "seedvr2/upscale",
  "label": {
    "en": "Upscale",
    "ru": "Апскейл"
  },
  "family": "seedvr2",
  "family_label": "SeedVR2 (restoration)",
  "tier": 0,
  "mode": "upscale",
  "order": 40,
  "controls": [
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "scale",
      "kind": "choice",
      "default": 2.0,
      "label": {
        "en": "Enlargement",
        "ru": "Увеличение"
      },
      "options": [
        {
          "value": 1.0,
          "label": "1x",
          "tooltip": {
            "en": "No enlargement - a second pass at the original size.",
            "ru": "Без увеличения — второй проход в исходном размере."
          }
        },
        {
          "value": 2.0,
          "label": "2x",
          "tooltip": {
            "en": "Twice the width and height.",
            "ru": "Вдвое по ширине и высоте."
          }
        },
        {
          "value": 4.0,
          "label": "4x",
          "tooltip": {
            "en": "Four times the width and height - slow, and best with a lower denoise.",
            "ru": "Вчетверо по ширине и высоте — долго, и лучше с меньшим денойзом."
          }
        }
      ]
    }
  ],
  "refs": {
    "max": 0
  },
  "requires": [
    "source_image"
  ],
  "upscale_params": {
    "image": "source_image"
  },
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "seedvr2_(7b|3b)"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "seedvr2_ema_vae"
    }
  ]
}
